package com.dunerealms.atelier;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.sql.*;import java.util.*;
class DeliveryStoreTest {
 final UUID owner=UUID.fromString("00000000-0000-0000-0009-000000000001"),other=UUID.fromString("00000000-0000-0000-0009-000000000002"),order=UUID.randomUUID();
 String design(){return "{\"blueprintId\":\""+UUID.randomUUID()+"\",\"name\":\"Desert Herald\",\"color\":\"#123456\",\"quality\":\"common\",\"lore\":[\"An original design.\"]}";}
 Connection database()throws Exception{Connection c=DriverManager.getConnection("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE");try(Statement s=c.createStatement()){s.execute("CREATE TABLE dune_kit_sales(id VARCHAR(36) PRIMARY KEY,buyer_uuid VARCHAR(36),snapshot_json TEXT,completed_at BIGINT,redeem_requested_at BIGINT,delivered_at BIGINT)");}try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_kit_sales(id,buyer_uuid,snapshot_json,completed_at) VALUES(?,?,?,1)")){q.setString(1,order.toString());q.setString(2,owner.toString());q.setString(3,design());q.executeUpdate();}return c;}
 @Test void wrongPlayerCannotLockPaidReceipt()throws Exception{try(Connection c=database()){c.setAutoCommit(false);assertThrows(SQLException.class,()->new DeliveryStore().lock(c,other,order));}}
 @Test void unfencedConnectionCannotConsume()throws Exception{try(Connection c=database()){assertThrows(SQLException.class,()->new DeliveryStore().lock(c,owner,order));assertThrows(SQLException.class,()->new DeliveryStore().delivered(c,owner,order,2));}}
 @Test void rolledBackCheckpointLeavesReceiptAvailable()throws Exception{try(Connection c=database()){c.setAutoCommit(false);DeliveryStore store=new DeliveryStore();store.lock(c,owner,order);store.delivered(c,owner,order,2);c.rollback();assertNotNull(store.lock(c,owner,order));assertEquals(1,store.pending(c,owner,false).size());}}
 @Test void committedReceiptCannotBeConsumedTwice()throws Exception{try(Connection c=database()){c.setAutoCommit(false);DeliveryStore store=new DeliveryStore();assertNotNull(store.lock(c,owner,order));store.delivered(c,owner,order,2);c.commit();assertThrows(SQLException.class,()->store.lock(c,owner,order));assertThrows(SQLException.class,()->store.delivered(c,owner,order,3));assertTrue(store.pending(c,owner,false).isEmpty());}}
 @Test void onlyExplicitlyQueuedReceiptsAutoDeliver()throws Exception{try(Connection c=database()){DeliveryStore store=new DeliveryStore();assertEquals(1,store.pending(c,owner,false).size());assertTrue(store.pending(c,owner,true).isEmpty());try(Statement s=c.createStatement()){s.executeUpdate("UPDATE dune_kit_sales SET redeem_requested_at=2");}assertEquals(1,store.pending(c,owner,true).size());}}
 @Test void malformedCosmeticsCannotReachItemFactory(){for(String replacement:List.of("<script>","§kHidden","x\n"))assertThrows(Exception.class,()->DeliveryStore.parse(design().replace("Desert Herald",replacement)));assertThrows(Exception.class,()->DeliveryStore.parse(design().replace("common","admin")));assertThrows(Exception.class,()->DeliveryStore.parse(design().replace("#123456","red")));assertThrows(Exception.class,()->DeliveryStore.parse(design().replace("\"An original design.\"","{}")));}
}
